__global__ void reduce_bug(const float* x, float* out, int N) {
    __shared__ float smem[256];
    int tid = threadIdx.x;
    int i = blockIdx.x * blockDim.x + tid;
    smem[tid] = (i < N) ? x[i] : 0.0f;
    // MISSING __syncthreads() here
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) smem[tid] += smem[tid + s];
        // MISSING __syncthreads() at end of loop body
    }
    if (tid == 0) atomicAdd(out, smem[0]);
}
